// raycaster.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



//*****************************************************************************
// App callbacks
//*****************************************************************************
static uint32_t s_lastTick;
             // end of the previous frame (for the frame cap)
static uint32_t s_lastUpd;
              // time of the previous update
static uint32_t s_owed;


static void PaceInit(void)
{
    s_lastTick = TimerNow();
    s_lastUpd  = s_lastTick;
    s_owed     = 0;
}


// Busy-wait until one frame period has passed since the previous frame ended.
// The counter counts DOWN, so elapsed = last - now (wrap-safe in uint32).
static void PaceWait(void)
{
    while((uint32_t)(s_lastTick - TimerNow()) < RC_FRAME_TICKS) { }
    s_lastTick = TimerNow();
}


// The game simulates at a fixed 30 ticks per second no matter how long drawing
// took: if a frame was slow, the missing ticks are run now (up to
// RC_MAX_CATCHUP), so walking speed, cooldowns and enemy speed stay in real
// time instead of slowing down with the frame rate.
static uint16_t TicksOwed(void)
{
    uint32_t now = TimerNow();
    uint16_t n   = 0;

    s_owed   += (uint32_t)(s_lastUpd - now);
    s_lastUpd = now;

    while(s_owed >= RC_FRAME_TICKS && n < RC_MAX_CATCHUP)
    {
        s_owed -= RC_FRAME_TICKS;
        n++;
    }
    if(s_owed > RC_FRAME_TICKS) s_owed = RC_FRAME_TICKS;    // too far behind: let go
    if(n == 0) { n = 1; s_owed = 0; }                       // always make progress
    return n;
}


// ---- MP3 theme: buzzer song until round 2, then track 10 loops ---------------
// rc_level counts rounds from 0, so round 2 is rc_level == 1.
#define RC_THEME_TRACK   10      // plays /MP3/0010.mp3
#define RC_THEME_SEC     120     // EDIT: length of 0010.mp3 in seconds (round up 1-2 s)
#define RC_THEME_FPS     400     // EDIT: frames per second (a guess); see note below
#define RC_THEME_ROUND   1       // rc_level value at which the MP3 takes over (1 = round 2)

static bool     s_rcThemeOn;     // true once the MP3 has taken over
static uint32_t s_rcThemeTimer;  // frames left in the current play of the track

static void RcTheme_Start(void)
{
    MP3_playTrack(RC_THEME_TRACK);
    s_rcThemeTimer = (uint32_t)RC_THEME_SEC * RC_THEME_FPS;
}

// Once per frame. Switches to the MP3 at round 2, then loops it.
static void RcTheme_Update(void)
{
    if(!s_rcThemeOn)
    {
        if(rc_level >= RC_THEME_ROUND)
        {
            s_rcThemeOn = true;
            Buzzer_Stop();                     // stop the buzzer song (and any sfx)
            RcTheme_Start();
        }
        return;
    }

    MP3_poll();                                // reads the module's "track done" message
    if(s_rcThemeTimer > 0) s_rcThemeTimer--;
    if(MP3_trackFinished() || s_rcThemeTimer == 0) RcTheme_Start();
}


static void RC_Init(void)
{
    uint16_t i;

    PaceInit();
    rc_BuildTables();
    rc_ResetRun();
    for(i = 0; i < RC_MAX_ENEMIES; i++) rc_en[i].alive = 0;
    for(i = 0; i < RC_MAX_OBJ; i++)     rc_obj[i].alive = 0;
    rc_stX = rc_stY = 0;
    rc_hud = 0;
    rc_StartLevel(0);

    s_rcThemeOn = false;                       // new run: buzzer song first
    MP3_stop();
    rc_EnterTitle();                           // title screen first; the music starts when you enter
}


static AppStatus RC_Update(void)
{
    uint16_t n, i;

    RcTheme_Update();

    switch(rc_mode)
    {
        case MODE_TITLE:
        case MODE_HOWTO:
        case MODE_LETTER:
            n = TicksOwed();
            if(rc_UpdateTitle(n))                    // letter dismissed: into the dungeon
            {
                rc_mode      = MODE_INTRO;
                rc_timer     = 75;
                rc_banner    = BAN_LEVEL;
                rc_dirtyFull = true;
                Buzzer_PlaySong(&song_corridor_run, 1);      // the dungeon theme begins
            }
            break;

        case MODE_INTRO:
            n = TicksOwed();
            rc_timer = (rc_timer > n) ? (uint16_t)(rc_timer - n) : 0;
            if(rc_timer == 0)
            {
                rc_mode       = MODE_PLAY;
                rc_invalidate = true;            // wipes the banner
                rc_viewDirty  = 2;
            }
            break;

        case MODE_PLAY:
            n = TicksOwed();
            for(i = 0; i < n && rc_mode == MODE_PLAY; i++)
            {
                rc_UpdatePlay();
                g_dpad.uPressed = g_dpad.dPressed = 0;      // button edges count once,
                g_dpad.lPressed = g_dpad.rPressed = 0;      // not once per catch-up tick
                g_joy.btnPressed = 0;
            }
            if(rc_lvPending && rc_mode == MODE_PLAY) rc_EnterCards();
            break;

        case MODE_CARDS:
            rc_UpdateCards();
            s_lastUpd = TimerNow();             // time spent choosing is not owed to the game
            s_owed    = 0;
            break;

        case MODE_CLEAR:
            n = TicksOwed();
            rc_timer = (rc_timer > n) ? (uint16_t)(rc_timer - n) : 0;
            if(rc_timer == 0)
            {
                rc_mode       = MODE_PLAY;
                rc_invalidate = true;            // wipes the banner
                rc_viewDirty  = 2;
                if(rc_lvPending) rc_EnterCards();
            }
            break;

        default:                                // OVER
            if(g_dpad.dPressed || g_joy.btnPressed) return APP_QUIT;
            break;
    }

    return APP_CONTINUE;
}


static void FullRepaint(void)
{
    if(rc_mode == MODE_TITLE || rc_mode == MODE_HOWTO || rc_mode == MODE_LETTER)
        rc_DrawTitleFull();
    else if(rc_mode == MODE_CARDS)
        rc_DrawCardsFull();
    else if(rc_mode == MODE_OVER)
        rc_DrawEndScreen();
    else
    {
        rc_DrawHudFrame();
        rc_hud        = HUD_ALL;
        rc_invalidate = true;
        rc_viewDirty  = 2;
        rc_cdShown    = -1;
        rc_manaShown  = -1;
        rc_bannerDraw = (rc_mode == MODE_INTRO || rc_mode == MODE_CLEAR);
    }
}


static void RC_RenderInner(void)
{
    if(rc_dirtyFull)
    {
        rc_dirtyFull = false;
        FullRepaint();
    }

    if(rc_mode == MODE_TITLE || rc_mode == MODE_HOWTO || rc_mode == MODE_LETTER)
    {
        rc_TitleRender();
        return;
    }

    if(rc_mode == MODE_CARDS)
    {
        rc_CardsRender();
        return;
    }

    if(rc_mode == MODE_OVER) return;

    if(rc_hud) rc_DrawHud();
    rc_DrawManaBar();

    if(rc_viewDirty)
    {
        rc_RenderView();
        rc_viewDirty--;
    }

    if(rc_mode == MODE_PLAY) rc_DrawCdStrip();

    if(rc_bannerDraw)
    {
        rc_DrawBanner();
        rc_bannerDraw = false;
    }
}


static void RC_Render(void)
{
    RC_RenderInner();
    PaceWait();
}


// After the pause overlay: repaint everything from the current state.
static void RC_Redraw(void)
{
    PaceInit();                                 // don't "catch up" after the pause
    rc_dirtyFull = true;
    if(rc_mode != MODE_OVER && rc_mode != MODE_TITLE && rc_mode != MODE_HOWTO && rc_mode != MODE_LETTER)
    {
        if(s_rcThemeOn) RcTheme_Start();                    // Settings interrupted the MP3
        else            Buzzer_PlaySong(&song_corridor_run, 1);
    }
}


static void RC_Exit(void)
{
    Buzzer_Stop();
    MP3_stop();
}


